async function cleanupDatabase(pool, schema) {
  try {
    // Only schemas generated by the test harness may be removed.
    if (!/^(adt_test_|migration_test_)[a-f0-9]{32}$/.test(schema)) throw new Error('Invalid test schema');
    await pool.query(`DROP SCHEMA IF EXISTS ${schema} CASCADE`);
  } finally {
    await pool.end();
  }
}
module.exports = { cleanupDatabase };
